create extension if not exists pgcrypto;

create table if not exists public.classes (
  id bigint generated by default as identity primary key,
  company_name text not null,
  category text,
  description text,
  class_types text[],
  minimum_age numeric,
  maximum_age numeric,
  age_range_display text,
  parental_requirement text,
  address text,
  eircode text,
  latitude double precision,
  longitude double precision,
  days_of_week text[],
  start_time text,
  end_time text,
  term_structure text,
  price_amount numeric,
  price_currency text,
  pricing_basis text,
  pricing_details text,
  website_url text,
  booking_url text,
  email_address text,
  phone_number text,
  facilities text[],
  source_urls text[],
  date_verified text,
  verification_status text,
  image_url text
);


alter table public.classes enable row level security;
create policy "Allow public read access" on public.classes
  for select
  using (true);

create policy "Allow public insert access" on public.classes
  for insert
  with check (true);

